import{z as o,x as A,o as i,c as d,q as r,j as s,D as e,d as t,s as B,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"多臂老虎机与 UCB","description":"","frontmatter":{"title":"多臂老虎机与 UCB","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bandit-ucb.md","filePath":"cs/bandit-ucb.md","lastUpdated":1791413859000}'),p={name:"cs/bandit-ucb.md"};function C(b,a,m,u,c,D){const n=A("Mermaid");return i(),d("div",null,[a[2]||(a[2]=r('<h1 id="多臂老虎机与-ucb" tabindex="-1">多臂老虎机与 UCB <a class="header-anchor" href="#多臂老虎机与-ucb" aria-label="Permalink to &quot;多臂老虎机与 UCB&quot;">​</a></h1><div class="epigraph"><p>探索未知臂与利用当前最好之间折中；UCB 用均值加 $\\sqrt{(\\log t)/n_i}$ 上置信界，遗憾 $O(\\log T)$。</p><footer>—— 据 Lai and Robbins, 1985；Auer, Cesa-Bianchi and Fischer, Finite-time Analysis of the Multiarmed Bandit, 2002 整理</footer></div><p>上一课<a href="/cs/secretary-problem">秘书问题</a>一次性选择。多臂：重复拉 \\(K\\) 臂，\\(T\\) 轮，奖励随机。缺口是遗憾（regret）与 UCB。不重写 \\(1/e\\)。本序列「不确定输入」在此结束。不写神经网络策略。下一序列近似算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>臂 \\(i\\) 均值 \\(\\mu_i\\)，\\(\\mu^*=\\max\\mu_i\\)。遗憾 \\(R_T=T\\mu^*-\\sum\\) 收益。贪心只利用会锁死次优。\\(\\varepsilon\\)-贪心：以 \\(\\varepsilon\\) 探索。UCB1：\\(i\\) 的指标 \\(\\bar x_i+\\sqrt{2\\ln t/n_i}\\)，拉最大者。次优臂拉 \\(O(\\log T)\\) 次，遗憾 \\(O(\\log T)\\)。</p><p>缺口是置信界探索，不是 MDP 全动态规划。</p><h3 id="不是广告拍卖课" tabindex="-1">不是广告拍卖课 <a class="header-anchor" href="#不是广告拍卖课" aria-label="Permalink to &quot;不是广告拍卖课&quot;">​</a></h3><p>同一公式可出现在推荐，本课算法遗憾。不写限价。</p><p><span class="marginnote">Lai–Robbins 渐近下界。Auer 等 2002 UCB1 有限时间。后课顶点覆盖 2-近似换离线近似。</span></p><p><span class="marginnote">术语翻译：UCB（Upper Confidence Bound，上置信界）就是「对每个臂估计它最好可能好到哪」，每轮挑这个乐观上界最大的臂——乐观是手段：不确定的臂上界虚高，先给它机会；等拉多了、区间收窄，虚高自动消失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每臂维护次数与和。每轮 UCB 选臂，观察奖励更新。\\(\\varepsilon\\) 可递减。下界：Lai–Robbins 对数遗憾必要（一定条件下）。</p>',12)),(i(),s(l,null,{default:e(()=>[B(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARM%5B%22K%20%E8%87%82%22%5D%20--%3E%20UCB%5B%22%E5%9D%87%E5%80%BC%20%2B%20%E7%BD%AE%E4%BF%A1%22%5D%0A%20%20UCB%20--%3E%20PULL%5B%22%E6%8B%89%E8%87%82%E8%A7%82%E5%AF%9F%22%5D%0A%20%20PULL%20--%3E%20REG%5B%22%E9%81%97%E6%86%BE%20O(log%20T)%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"分布有界假设（Hoeffding）。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是不确定性主动清零：欠拉的臂置信区间宽、上界虚高，指标把它顶到最前，算法被迫探索；拉够之后区间收窄、虚高消失，真次优臂被永久让位——探索不靠外生掷骰子，是置信几何自己产生的。与秘书对照：秘书不能回头拉，bandit 每轮重新选；与混合时间对照：这里奖励 i.i.d.、无状态转移，不是图游走。",-1)),(i(),s(l,null,{default:e(()=>[B(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%87%82%20A%3A%20%E6%8B%89%20999%20%E6%AC%A1%2C%20%E5%9D%87%E5%80%BC%200.8%22%5D%20--%3E%20IA%5B%22%E5%8A%A0%E9%A1%B9%E7%AA%84%2C%20%E6%8C%87%E6%A0%87%E7%BA%A6%200.92%22%5D%0A%20%20B%5B%22%E8%87%82%20B%3A%20%E5%8F%AA%E6%8B%89%201%20%E6%AC%A1%2C%20%E5%9D%87%E5%80%BC%200.9%22%5D%20--%3E%20IB%5B%22%E5%8A%A0%E9%A1%B9%E5%AE%BD%2C%20%E6%8C%87%E6%A0%87%E8%99%9A%E9%AB%98%E5%88%B0%E7%BA%A6%204.6%22%5D%0A%20%20IB%20--%3E%20SEL%5B%22%E6%9C%AC%E8%BD%AE%E6%8C%87%E6%A0%87%E6%9C%80%E5%A4%A7%2C%20B%20%E8%A2%AB%E9%80%89%E4%B8%AD%22%5D%0A%20%20SEL%20--%3E%20UP%5B%22n%20%E5%A2%9E%E5%A4%A7%2C%20%E5%8A%A0%E9%A1%B9%E6%8C%89%E6%A0%B9%E5%8F%B7%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20UP%20--%3E%20DEC%7B%22%E5%9D%87%E5%80%BC%E6%92%91%E5%BE%97%E4%BD%8F%E4%B8%8A%E7%95%8C%E5%90%97%3F%22%7D%0A%20%20DEC%20--%3E%7C%22%E6%92%91%E4%B8%8D%E4%BD%8F%22%7C%20LOSE%5B%22%E5%9B%9E%E8%90%BD%E8%AE%A9%E4%BD%8D%2C%20%E9%81%97%E6%86%BE%E5%8F%AA%E4%BB%98%E8%BF%99%E5%87%A0%E6%AC%A1%22%5D%0A%20%20DEC%20--%3E%7C%22%E6%92%91%E5%BE%97%E4%BD%8F%22%7C%20WIN%5B%22%E7%BB%A7%E7%BB%AD%E8%A2%AB%E9%80%89%2C%20%E6%88%90%E4%B8%BA%E6%96%B0%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">数字实例：\\(t=1000\\) 时 \\(\\sqrt{2\\ln t}\\approx 3.7\\)。臂 A 拉过 999 次，加项约 \\(3.7/\\sqrt{999}\\approx 0.12\\)，指标约 \\(0.92\\)；臂 B 只拉过 1 次，加项约 \\(3.7\\)，哪怕均值只有 \\(0.9\\)，指标高达 \\(4.6\\)——于是 B 被拉，这就是「欠拉自动被探索」背后的算术。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写对抗 bandit（Exp3）、不写上下文 bandit 全文。后课默认：随机 bandit 用 UCB，遗憾对数。下一课顶点覆盖 2-近似。</p><p><span class="marginnote">直觉类比：探索–利用就像选晚饭——常去的那家（当前最优臂）不会难吃，但巷口新开的店（欠拉臂）可能更好；UCB 给「没试过的新店」记一笔「可能更好」的加分，试过几次加分自然衰减，决策慢慢回到真实排名。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>遗憾权衡探索/利用。</li><li>UCB 上置信界，\\(O(\\log T)\\)。</li><li>贪心可锁死。</li><li>出处：Lai and Robbins, 1985；Auer, Cesa-Bianchi and Fischer, 2002。</li></ul>',6))])}const f=o(p,[["render",C]]);export{_ as __pageData,f as default};
